mapper.select:
select s.id, s.student_no, s.student_name, s.student_phone, s.education, s.grade_year, s.school, s.major, s.teaching_mode, s.class_id, c.class_period, pc.product_content, s.student_tag, s.status, case when sop.id is null then false else true end as sop_assigned, sop.id as sop_id, sop.mentor_id as sop_mentor_id, coalesce(nullif(u.real_name, ''), nullif(u.nickname, ''), u.username) as sop_mentor_name, sop.sop_video_object_key, sop.sop_video_file_name, sop.sop_time, s.created_at, s.updated_at from student s left join sys_class c on c.id = s.class_id left join ( select sp.student_id, group_concat(distinct op.course_content order by op.id separator '、') as product_content from student_product sp inner join order_product op on op.id = sp.product_id where sp.status = 'ACTIVE' group by sp.student_id ) pc on pc.student_id = s.id left join ( select ss.* from student_sop ss inner join ( select student_id, max(id) as id from student_sop where status != 'CANCELED' group by student_id ) latest on latest.id = ss.id ) sop on sop.student_id = s.id left join sys_user u on u.id = sop.mentor_id
and s.student_name like concat('%', #{studentName}, '%') and s.student_phone like concat('%', #{studentPhone}, '%') and s.education = #{education} and s.school like concat('%', #{school}, '%') and s.teaching_mode = #{teachingMode} and s.student_tag = #{studentTag} and s.status = #{status}
order by s.id desc
